// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Live vendor transport with deadline, key files, adapter dispatch
// Flo: worker thread sends HTTP (GET/POST) > caller polls to deadline > Real backend loads key file > picks adapter by vendor > redacts the key from errors
// I/O: Http (adapters) > Back; Req + vendor (ladder) > Rsp; keys read from vend_keyz_dirz/<vend>.key (first line, trimmed)
// ===================================================================
const std = @import("std"); const http = std.http; const flate = std.compress.flate; const base = @import("nt-vend-base.zig"); const zenr = @import("nt-vend-zenr.zig"); const deco = @import("nt-vend-deco.zig"); const brig = @import("nt-vend-brig.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .poll = 10, .maxb = 20 << 20, .trnb = 8192, .redb = 4096, .keyz = 4096 };
const Job = struct { allo: std.mem.Allocator, iozz: std.Io, urlz: []u8, auth: []u8, ctyp: []u8, body: []u8, post: bool, meth: []u8, heds: []http.Header, stat: std.atomic.Value(u8) = .init(0), resz: anyerror!base.Back = error.Unexpected,
fn kill(self: *Job) void { const allo = self.allo; allo.free(self.urlz); allo.free(self.auth); allo.free(self.ctyp); allo.free(self.body); allo.free(self.meth); for (self.heds) |hed| { allo.free(hed.name); allo.free(hed.value); } allo.free(self.heds); allo.destroy(self); } };
fn doReq(job: *Job) !base.Back { const allo = job.allo; var clnt: http.Client = .{ .allocator = allo, .io = job.iozz }; defer clnt.deinit(); const uric = try std.Uri.parse(job.urlz); const mthd: http.Method = if (job.meth.len > 0) (std.meta.stringToEnum(http.Method, job.meth) orelse return error.BadMethod) else if (job.post) .POST else .GET; var req = try clnt.request(mthd, uric, .{ .keep_alive = false, .redirect_behavior = .unhandled, .extra_headers = job.heds, .headers = .{ .authorization = if (job.auth.len > 0) .{ .override = job.auth } else .default, .content_type = if (job.ctyp.len > 0) .{ .override = job.ctyp } else .default } }); defer req.deinit(); if (job.post or mthd == .PUT) { req.transfer_encoding = .{ .content_length = job.body.len }; const bodz = try allo.dupe(u8, job.body); defer allo.free(bodz); try req.sendBodyComplete(bodz); } else { try req.sendBodiless(); } var redb: [CF.redb]u8 = undefined; var resp = try req.receiveHead(&redb); const code: u16 = @backingInt(resp.head.status); const trnb = try allo.alloc(u8, CF.trnb); defer allo.free(trnb); const winb = try allo.alloc(u8, flate.max_window_len); defer allo.free(winb); var deco_: http.Decompress = undefined; const rdrz = resp.readerDecompressing(trnb, &deco_, winb); const body = rdrz.allocRemaining(allo, .limited(CF.maxb)) catch |err| switch (err) { error.StreamTooLong => return error.TooBig, error.OutOfMemory => return error.OutOfMemory, error.ReadFailed => return resp.bodyErr() orelse error.ReadFailed }; return .{ .code = code, .body = body }; }
fn work(job: *Job) void { job.resz = doReq(job); if (job.stat.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) { if (job.resz) |back| job.allo.free(back.body) else |_| {} job.kill(); } }
fn hedsDup(allo: std.mem.Allocator, src: []const base.Hdr) ![]http.Header { const outp = try allo.alloc(http.Header, src.len); for (src, 0..) |hed, ix| outp[ix] = .{ .name = try allo.dupe(u8, hed.name), .value = try allo.dupe(u8, hed.valu) }; return outp; }
pub const Live = struct { time_mill: u32 = 30000,
pub fn send(self: *Live) base.Send { return .{ .ctx = self, .call = callz }; }
fn callz(ctx: *anyopaque, gpaz: std.mem.Allocator, iozz: std.Io, htp: base.Http) anyerror!base.Back { const self: *Live = @ptrCast(@alignCast(ctx)); const job = try gpaz.create(Job); var armd = false; errdefer if (!armd) gpaz.destroy(job); job.* = .{ .allo = gpaz, .iozz = iozz, .urlz = try gpaz.dupe(u8, htp.urlz), .auth = try gpaz.dupe(u8, htp.auth), .ctyp = try gpaz.dupe(u8, htp.ctyp), .body = try gpaz.dupe(u8, htp.body), .post = htp.post, .meth = try gpaz.dupe(u8, htp.meth), .heds = try hedsDup(gpaz, htp.extra) }; const thrd = std.Thread.spawn(.{}, work, .{job}) catch { job.kill(); return error.Unexpected; }; thrd.detach(); armd = true; const dead = std.Io.Clock.awake.now(iozz).toMilliseconds() + self.time_mill; while (job.stat.load(.acquire) != 1) { if (std.Io.Clock.awake.now(iozz).toMilliseconds() >= dead) { if (job.stat.cmpxchgStrong(0, 2, .acq_rel, .acquire) == null) return error.Timeout; break; } std.Io.sleep(iozz, .fromMilliseconds(CF.poll), .awake) catch {}; } const outp = job.resz; job.kill(); return outp; } };
pub const Real = struct { gpaz: std.mem.Allocator, conf: cfgz.Conf, keyd: []const u8, live: Live = .{},
pub fn backend(self: *Real) base.Backend { return .{ .ctx = self, .call = callz }; }
pub fn keyLoad(self: *Real, aren: std.mem.Allocator, iozz: std.Io, vend: base.Vend) ![]const u8 { const path = try std.fmt.allocPrint(aren, "{s}{s}{s}.key", .{ self.keyd, std.fs.path.sep_str, base.vendName(vend) }); const raws = std.Io.Dir.cwd().readFileAlloc(iozz, path, aren, .limited(CF.keyz)) catch return error.NoKey; const line = std.mem.sliceTo(std.mem.trim(u8, raws, " \t\r\n"), '\n'); const key = std.mem.trim(u8, line, " \t\r"); if (key.len == 0) return error.NoKey; return key; }
fn callz(ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, vend: base.Vend, req: base.Req) anyerror!base.Rsp { const self: *Real = @ptrCast(@alignCast(ctx)); const key = try self.keyLoad(aren, iozz, vend); const snd = self.live.send(); var rsp = switch (vend) { .zenr => try zenr.call(aren, self.gpaz, iozz, snd, key, req), .deco => try deco.call(aren, self.gpaz, iozz, snd, key, req), .brig => try brig.call(aren, self.gpaz, iozz, snd, key, self.conf.vend_zone_brig, req), .mock => return error.NoKey }; rsp.errz = try base.redact(aren, rsp.errz, key); return rsp; } };
